// Generated by EmbedCo
// Board: Arduino Uno (uno)
// Install these libraries: NewPing

#include <NewPing.h>
#include <Servo.h>

NewPing sonar1(9, 10, 400);
Servo servo1;

void setup() {
    servo1.attach(6);
}

void loop() {
    if ((sonar1.ping_cm() < 20)) {
        servo1.write(constrain(90, 0, 180));
    } else {
        servo1.write(constrain(0, 0, 180));
    }
}

