void setup() {
    Serial.begin(115200);
    pinMode(13, OUTPUT);
}

void loop() {
    {
        static unsigned long cf_last_1 = 0;
        if (millis() - cf_last_1 >= (unsigned long)(500)) {
            cf_last_1 = millis();
            digitalWrite(13, true ? HIGH : LOW);
            delay(100);
        }
    }
    for (int cf_i2 = 0, cf_n2 = (3); cf_i2 < cf_n2; cf_i2++) {
        delay(10);
    }
}

